import{_ as e,o,c as r,a2 as t}from"./chunks/framework.DHtetOlu.js";const p=JSON.parse('{"title":"Malha e materiais","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mesh.md","filePath":"guide/mesh.md"}'),i={name:"guide/mesh.md"};function s(n,a,d,m,l,c){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="malha-e-materiais" tabindex="-1">Malha e materiais <a class="header-anchor" href="#malha-e-materiais" aria-label="Permalink to &quot;Malha e materiais&quot;">​</a></h1><p>A etapa <strong>Malha</strong> transforma o desenho num problema físico: o MagFEM detecta as <strong>regiões</strong> fechadas, você diz de que material cada uma é, onde há corrente e quais são as condições de contorno, e então gera a malha de triângulos.</p><h2 id="regioes" tabindex="-1">Regiões <a class="header-anchor" href="#regioes" aria-label="Permalink to &quot;Regiões&quot;">​</a></h2><p>Toda área fechada pelas curvas vira uma região, detectada automaticamente e numerada (&quot;Região 1&quot;, &quot;Região 2&quot;…). Linhas de construção não formam regiões. A região mantém o que foi atribuído a ela mesmo quando o desenho muda: ela é identificada por um ponto interno, como os <em>block labels</em> do FEMM.</p><ul><li>Clique numa região no desenho para selecioná-la; duplo clique no nome (na árvore) renomeia.</li><li>O rótulo da região pode ser arrastado no desenho.</li><li>Uma região sem material não entra na malha (como no FEMM).</li></ul><div class="warning custom-block"><p class="custom-block-title">Curvas sobrepostas</p><p>Duas linhas uma sobre a outra no mesmo trecho não fecham regiões direito. Divida as linhas nos pontos de contato (a <a href="./geometry.html#editar">tesoura</a> ajuda) em vez de sobrepor.</p></div><h2 id="materiais" tabindex="-1">Materiais <a class="header-anchor" href="#materiais" aria-label="Permalink to &quot;Materiais&quot;">​</a></h2><p>Em <strong>Malha › Materiais</strong>, cada região tem uma lista de materiais com busca. A biblioteca fica na gaveta da direita (<strong>Problema e bibliotecas › Materiais</strong>):</p><ul><li><strong>Grupos</strong>: ar, condutores, aços (com curva B-H), ímãs e os seus.</li><li><strong>Propriedades</strong>: permeabilidade relativa μr, condutividade σ (MS/m), remanência Br (T) para ímãs, cor, e os coeficientes de Steinmetz para perdas no ferro (k_h, α, k_e; usados na análise AC).</li><li><strong>Curva B-H</strong>: materiais com curva são não lineares. A curva aparece numa aba própria, com escala linear ou log.</li><li><strong>Biblioteca do FEMM 4.2</strong>: 245 materiais prontos na busca. <strong>Importar do FEMM…</strong> também lê o <code>matlib.dat</code> da sua instalação.</li><li>Para ímãs, a <strong>direção de magnetização</strong> (ângulo) é definida na região.</li></ul><h2 id="circuitos-e-correntes" tabindex="-1">Circuitos e correntes <a class="header-anchor" href="#circuitos-e-correntes" aria-label="Permalink to &quot;Circuitos e correntes&quot;">​</a></h2><p>Em <strong>Malha › Circuitos</strong>, <code>+</code> cria um circuito com uma <strong>corrente</strong> (em A; aceita variáveis e, no transitório, funções de <code>t</code>, como <code>2*sin(2*pi*60*t)</code>). Nas propriedades da região, ligue-a a um circuito com um número de <strong>espiras</strong>; espiras negativas invertem o sentido (ida e volta de uma bobina).</p><ul><li>Todas as regiões de um circuito levam a mesma corrente (circuito <strong>série</strong>). O tipo &quot;paralelo&quot; dos arquivos do FEMM é guardado, mas a divisão da corrente entre regiões em paralelo ainda não foi implementada.</li><li>Uma região também pode ter corrente própria, sem circuito.</li></ul><p>A densidade de corrente é J = N·I / área da região.</p><h2 id="contornos" tabindex="-1">Contornos <a class="header-anchor" href="#contornos" aria-label="Permalink to &quot;Contornos&quot;">​</a></h2><p>A borda externa do domínio entra automaticamente em <strong>Dirichlet (A = 0)</strong>: o fluxo não atravessa essa borda. Para outros contornos, clique nas bordas no desenho (Shift para várias) e escolha o contorno; os tipos ficam na gaveta da direita, com os mesmos nomes do FEMM:</p><table tabindex="0"><thead><tr><th>Tipo</th><th>Condição</th><th>Uso</th></tr></thead><tbody><tr><td>A prescrito (Dirichlet)</td><td>A = A0 + A1·x + A2·y (x, y em m)</td><td>A = 0 na borda; campo uniforme imposto com A1/A2</td></tr><tr><td>Neumann</td><td>∂A/∂n = 0</td><td>simetria magnética: o fluxo cruza a curva perpendicularmente</td></tr><tr><td>Misto (Robin)</td><td>ν ∂A/∂n + c0·A + c1 = 0</td><td>borda aberta assintótica: c0 = 1/(μ0·R), c1 = 0, com R o raio do domínio em m</td></tr><tr><td>Periódico</td><td>A igual no par de curvas</td><td>repete o domínio (um polo de uma máquina)</td></tr><tr><td>Antiperiódico</td><td>A com sinal trocado no par</td><td>meio período</td></tr></tbody></table><p>Periódico e antiperiódico ligam <strong>pares</strong> de curvas: selecione as duas. A malha é gerada casando os nós das duas curvas. Os tipos &quot;pequena profundidade de penetração&quot;, &quot;imagem dual&quot; e &quot;entreferro periódico&quot; existem para ler arquivos do FEMM, mas ainda não são resolvidos.</p><p>No axissimétrico, o eixo r = 0 tem sempre A = 0 (ψ = r·A se anula no eixo).</p><h2 id="gerar-a-malha" tabindex="-1">Gerar a malha <a class="header-anchor" href="#gerar-a-malha" aria-label="Permalink to &quot;Gerar a malha&quot;">​</a></h2><p>A malha usa o <strong>Tangle</strong>, o gerador do FEMM (de David Meeker, licença MIT), compilado para WebAssembly.</p><ul><li><strong>Elementos</strong>: tamanho padrão do elemento (vazio = automático) e <strong>ângulo mínimo</strong> (qualidade: nenhum triângulo terá ângulo interno menor; 30° é um bom padrão, 34° é o máximo aceito). ▶ gera a malha.</li><li><strong>Regiões</strong>: tamanho do elemento por região, para refinar onde o campo varia mais (entreferro, cantos, núcleo).</li><li><strong>Por curva</strong>: tamanho ao longo de curvas escolhidas (<code>m.curve_size</code> no console).</li><li>As propriedades de <strong>Elementos</strong> mostram nós, triângulos, o menor ângulo e o tempo, com um mapa de qualidade.</li></ul><p>Resolver sem malha gera a malha antes, automaticamente.</p>',22)])])}const g=e(i,[["render",s]]);export{p as __pageData,g as default};
